 const done=()=>{ctx.restore();if(p.code){ctx.font='bold '+(p.evolved?22:19)+'px monospace';ctx.textAlign='center';ctx.fillStyle=p.evolved?'#e3b7ff':'#b6ffec';ctx.fillText(p.evolved?'{</>}':'</>',p.x,p.y-15)}};
 const streak=(len,c,w)=>{let g=ctx.createLinearGradient?.(-len,0,0,0);if(g){g.addColorStop(0,c+'00');g.addColorStop(1,c)}ctx.strokeStyle=g||c;ctx.lineWidth=lw(w);ctx.beginPath();ctx.moveTo(-len,0);ctx.lineTo(0,0);ctx.stroke()};
