 if(p.hovSpear){glow('#f7da8a',10);ctx.strokeStyle='#20132f';ctx.lineWidth=lw(7);ctx.beginPath();ctx.moveTo(-62,0);ctx.lineTo(16,0);ctx.stroke();ctx.strokeStyle='#f7da8a';ctx.lineWidth=lw(3.2);ctx.stroke();ctx.fillStyle='#fff0b4';ctx.beginPath();ctx.moveTo(34,0);ctx.lineTo(8,-10);ctx.lineTo(14,0);ctx.lineTo(8,10);ctx.closePath();ctx.fill();if(p.hovStage>=2){ctx.strokeStyle='#b792eb';ctx.lineWidth=lw(2);ctx.beginPath();ctx.ellipse(-30,0,10,19,0,0,Math.PI*2);ctx.stroke()}return done()}
 if(p.dioKnife){ctx.rotate(spin*.15);ctx.fillStyle='#e9eef2';ctx.strokeStyle='#5a6470';ctx.lineWidth=lw(1.5);ctx.beginPath();ctx.moveTo(26,0);ctx.lineTo(-4,-6);ctx.lineTo(-6,6);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#c8a64a';ctx.fillRect(-14,-3,9,6);ctx.fillStyle='#3b2a1a';ctx.fillRect(-22,-2.5,8,5);return done()}
 if(p.genjiDart||hero==='genji'){/* 绿色拖尾 */let tg=ctx.createLinearGradient?.(-48,0,0,0);if(tg){tg.addColorStop(0,'rgba(124,245,176,0)');tg.addColorStop(1,'rgba(124,245,176,.75)')}ctx.strokeStyle=tg||'rgba(124,245,176,.6)';ctx.lineWidth=lw(7);ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-48,0);ctx.lineTo(-4,0);ctx.stroke();ctx.rotate(spin);glow('#7cf5b0',8);ctx.fillStyle='#d9ffe9';ctx.strokeStyle='#2c6b4a';ctx.lineWidth=lw(1.5);ctx.beginPath();for(let n=0;n<3;n++){let a=n*2*Math.PI/3;ctx.lineTo(Math.cos(a)*16,Math.sin(a)*16);ctx.lineTo(Math.cos(a+Math.PI/3)*5,Math.sin(a+Math.PI/3)*5)}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#2c6b4a';ctx.beginPath();ctx.arc(0,0,3,0,Math.PI*2);ctx.fill();return done()}
