 if(p.itemRocket||p.dvaMissile||hero==='dva'&&p.index===0){let c=p.dvaMissile||hero==='dva'?'#ff7fc6':'#ffb35a';ctx.fillStyle='#ffffff55';for(let n=1;n<4;n++){ctx.beginPath();ctx.arc(-10-n*8,Math.sin(spin+n)*2,3+n*1.5,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#e9e2f0';ctx.fillRect(-10,-3.5,20,7);ctx.fillStyle=c;ctx.beginPath();ctx.moveTo(18,0);ctx.lineTo(10,-4);ctx.lineTo(10,4);ctx.closePath();ctx.fill();ctx.fillStyle='#ffd27a';ctx.beginPath();ctx.moveTo(-10,-3);ctx.lineTo(-18,0);ctx.lineTo(-10,3);ctx.fill();return done()}
