 if(hero==='lux'){glow('#fff3a8',16);let r2=Math.max(9,Math.min(22,(p.radius||10)*.9));ctx.fillStyle='#fffbe0';ctx.beginPath();ctx.arc(0,0,r2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ffe27a';ctx.lineWidth=lw(2);ctx.rotate(spin*.4);for(let n=0;n<4;n++){ctx.rotate(Math.PI/4);ctx.beginPath();ctx.moveTo(-r2*1.8,0);ctx.lineTo(r2*1.8,0);ctx.stroke()}return done()}
 if(hero==='zero'){ctx.rotate(spin*.5);glow('#67f5d2',10);ctx.fillStyle='#0d2a33';ctx.strokeStyle='#67f5d2';ctx.lineWidth=lw(2);ctx.fillRect(-9,-9,18,18);ctx.strokeRect(-9,-9,18,18);ctx.fillStyle='#67f5d2';ctx.fillRect(-3,-3,6,6);return done()}
 if(hero!=='cassidy'&&hero!=='tracer'&&window.SkillFxV21?.trail)window.SkillFxV21.trail(ctx,p,spin,hero);if(hero==='zarya'&&window.ZaryaFxV20?.projectile(ctx,p,spin))return done();if(hero==='lux'&&window.LuxFxV20?.projectile(ctx,p,spin))return done();if(hero==='cassidy'){ctx.shadowColor='#ffd27a';ctx.shadowBlur=10;ctx.strokeStyle='rgba(255,230,160,.85)';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-34,0);ctx.lineTo(0,0);ctx.stroke();ctx.fillStyle='#fff6d0';ctx.beginPath();ctx.arc(0,0,4,0,Math.PI*2);ctx.fill();return done()}
 if(hero==='zarya'){glow('#ff9ae6',14);let r2=Math.max(9,Math.min(20,(p.radius||10)));ctx.fillStyle='#ffd6f5';ctx.beginPath();ctx.arc(0,0,r2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ff7ad9';ctx.lineWidth=lw(2.5);ctx.beginPath();ctx.ellipse(0,0,r2*1.5,r2*.55,spin,0,Math.PI*2);ctx.stroke();return done()}
 if(hero==='yasuo'&&!p.yasuoTornado){glow('#a4e8ff',8);ctx.strokeStyle='#d8f6ff';ctx.lineWidth=lw(3);ctx.beginPath();ctx.arc(-8,0,22,-1.1,1.1);ctx.stroke();ctx.strokeStyle='#72c9ed';ctx.lineWidth=lw(1.5);ctx.beginPath();ctx.arc(-16,0,18,-1,1);ctx.stroke();return done()}
 if(p.khazixW||hero==='khazix'){glow('#c58bff',12);streak(46,'#9b5cff',5);ctx.fillStyle='#2a1440';ctx.strokeStyle='#d9b8ff';ctx.lineWidth=lw(2);ctx.beginPath();ctx.moveTo(26,0);ctx.lineTo(-6,-7);ctx.lineTo(-2,0);ctx.lineTo(-6,7);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle='#e9d6ff';ctx.lineWidth=lw(1.5);for(let n of [-1,1]){ctx.beginPath();ctx.moveTo(4,0);ctx.lineTo(-8,n*12);ctx.stroke()}return done()}
 if(hero==='illaoi'&&p.illaoiSpirit&&src.x!=null){/* V20 俄洛伊E：从抱着的神像里伸出的绿色半透明触手，一直连到飞行中的灵魂抓手 */let dx=src.x-p.x,dy=src.y-p.y,c=Math.cos(angle),s=Math.sin(angle),lx=dx*c+dy*s,ly=-dx*s+dy*c,L=Math.hypot(lx,ly),n=Math.max(6,Math.round(L/22));glow('#7dffb0',14);ctx.lineCap='round';ctx.beginPath();for(let i=0;i<=n;i++){let f=i/n,wv=Math.sin(f*9-spin*2)*7*Math.sin(f*Math.PI);ctx.lineTo(lx*(1-f)-ly*0+(-ly/L||0)*wv,ly*(1-f)+(lx/L||0)*wv)}ctx.strokeStyle='rgba(93,255,160,.35)';ctx.lineWidth=lw(16);ctx.stroke();ctx.strokeStyle='rgba(170,255,205,.7)';ctx.lineWidth=lw(6);ctx.stroke();ctx.strokeStyle='rgba(235,255,242,.9)';ctx.lineWidth=lw(2);ctx.stroke();ctx.fillStyle='rgba(200,255,225,.75)';ctx.beginPath();ctx.ellipse(6,0,13,9,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba(93,255,160,.9)';ctx.lineWidth=lw(2);ctx.stroke();for(let n2 of [-1,1]){ctx.beginPath();ctx.moveTo(12,n2*5);ctx.quadraticCurveTo(22,n2*12,26,n2*4);ctx.stroke()}return done()}
 if(hero==='illaoi'){glow('#7dffb0',12);let w=Math.sin(spin*1.4)*5;ctx.strokeStyle='#3fd38a';ctx.lineWidth=lw(6);ctx.beginPath();ctx.moveTo(-52,0);ctx.quadraticCurveTo(-30,w*2,-10,-w);ctx.quadraticCurveTo(2,w,10,0);ctx.stroke();ctx.strokeStyle='#c8ffe0';ctx.lineWidth=lw(2);ctx.stroke();ctx.fillStyle='#e9fff3';ctx.beginPath();ctx.ellipse(12,0,9,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#1d6b45';ctx.beginPath();ctx.arc(14,0,2.5,0,Math.PI*2);ctx.fill();return done()}
 if(structure){let tc=src.team===1?'#ff7a6a':'#7fc8ff';glow(tc,18);streak(70,tc,10);ctx.fillStyle='#fff3c8';ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();ctx.strokeStyle=tc;ctx.lineWidth=lw(3);ctx.stroke();ctx.rotate(spin*.6);ctx.strokeStyle='#ffd27a';ctx.lineWidth=lw(2);ctx.beginPath();ctx.ellipse(0,0,19,6,0,0,Math.PI*2);ctx.stroke();return done()}
