window.drawCombatImpact=function(ctx,u,time){let v=u.rangedImpactVisual;if(!v||time>=v.end)return;let p=Math.max(0,Math.min(1,(time-v.start)/(v.end-v.start)));ctx.save();ctx.translate(v.x,v.y);ctx.strokeStyle=v.color;ctx.globalAlpha=1-p;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,10+p*22,0,Math.PI*2);ctx.stroke();for(let i=0;i<4;i++){let a=i*Math.PI/2;ctx.beginPath();ctx.moveTo(Math.cos(a)*8,Math.sin(a)*8);ctx.lineTo(Math.cos(a)*(20+p*16),Math.sin(a)*(20+p*16));ctx.stroke()}ctx.restore()};
